from itertools import product

c = [0] * 10
fixed_values = {3: 1, 9: 0}

for p in product([0, 1], repeat=10):
    c = list(p)
    if all(c[i] == fixed_values[i] for i in fixed_values):
        valid = True
        for i in range(5):
            for j in range(i + 1, 5):
                for k in range(j + 1, 5):
                    idx1 = i * 4 + j if i * 4 + j < 10 else (j * 4 + i) - 10
                    idx2 = j * 4 + k if j * 4 + k < 10 else (k * 4 + j) - 10
                    idx3 = k * 4 + i if k * 4 + i < 10 else (i * 4 + k) - 10
                    if c[idx1] == c[idx2] == c[idx3] == 0 or c[idx1] == c[idx2] == c[idx3] == 1:
                        valid = False
                        break
                if not valid:
                    break
            if not valid:
                break
        if valid:
            print(c)
            break
